+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">import</span> pandas <span class="kw">as</span> pd\n<span class="kw">import</span> numpy <span class="kw">as</span> np\n\ndf = pd.<span class="fn">DataFrame</span>({\n    <span class="str">"name"</span>: [<span class="str">"Alice"</span>, <span class="str">"Bob"</span>, <span class="str">"Carol"</span>, <span class="str">"Dave"</span>, <span class="str">"Eve"</span>],\n    <span class="str">"age"</span>: [<span class="num">25</span>, <span class="num">30</span>, <span class="num">28</span>, <span class="num">35</span>, <span class="num">22</span>],\n    <span class="str">"score_math"</span>: [<span class="num">88</span>, <span class="num">72</span>, <span class="num">95</span>, <span class="num">60</span>, <span class="num">91</span>],\n    <span class="str">"score_nlp"</span>: [<span class="num">92</span>, <span class="num">85</span>, <span class="num">78</span>, <span class="num">88</span>, <span class="num">96</span>],\n    <span class="str">"field"</span>: [<span class="str">"NLP"</span>, <span class="str">"CV"</span>, <span class="str">"RL"</span>, <span class="str">"NLP"</span>, <span class="str">"CV"</span>]\n})\n\n<span class="cm"># Single column \u2192 Series</span>\nnames = df[<span class="str">"name"</span>]        <span class="cm"># \u2190 preferred</span>\nnames = df.name             <span class="cm"># same result, but fragile</span>\n<span class="fn">print</span>(<span class="fn">type</span>(names))         <span class="cm"># &lt;class \'pandas.core.series.Series\'&gt;</span>\n\n<span class="cm"># Multiple columns \u2192 DataFrame</span>\nsubset = df[[<span class="str">"name"</span>, <span class="str">"age"</span>]]   <span class="cm"># note double brackets</span>\n<span class="fn">print</span>(<span class="fn">type</span>(subset))             <span class="cm"># &lt;class \'pandas.core.frame.DataFrame\'&gt;</span>\n\n<span class="cm"># Regex column selection with filter()</span>\nscore_cols = df.<span class="fn">filter</span>(regex=<span class="str">"^score_"</span>)  <span class="cm"># columns starting with \'score_\'</span>\n<span class="fn">print</span>(score_cols.columns)  <span class="cm"># Index([\'score_math\', \'score_nlp\'])</span>\n\n<span class="cm"># filter by substring (like=) or exact items</span>\ndf.<span class="fn">filter</span>(like=<span class="str">"score"</span>)        <span class="cm"># columns containing \'score\'</span>\ndf.<span class="fn">filter</span>(items=[<span class="str">"name"</span>,<span class="str">"age"</span>]) <span class="cm"># exact column names</span></code></pre></div>'

