+ '<div class="calc-card"><div class="card-title">Transform</div><div class="card-body">.str.replace(), .str.strip(), .str.split(), .str.slice(), .str.pad(), .str.zfill()</div></div>'
+ '<div class="calc-card"><div class="card-title">Extract</div><div class="card-body">.str.extract() with regex groups, .str.findall(), .str.len(), .str.count() for text mining.</div></div>'
+ '</div>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">import</span> pandas <span class="kw">as</span> pd\n\ndf = pd.<span class="fn">DataFrame</span>({\n    <span class="str">"text"</span>: [\n        <span class="str">"Natural Language Processing is fun!"</span>,\n        <span class="str">"Deep Learning with PyTorch"</span>,\n        <span class="str">"  sentiment analysis  "</span>,\n        <span class="str">"NER: Named Entity Recognition"</span>,\n        <span class="str">"transformers for NLP tasks"</span>\n    ],\n    <span class="str">"label"</span>: [<span class="str">"pos"</span>, <span class="str">"pos"</span>, <span class="str">"neg"</span>, <span class="str">"pos"</span>, <span class="str">"neg"</span>]\n})\n\n<span class="cm"># Case conversion</span>\ndf[<span class="str">"lower"</span>] = df[<span class="str">"text"</span>].str.<span class="fn">lower</span>()\ndf[<span class="str">"upper"</span>] = df[<span class="str">"text"</span>].str.<span class="fn">upper</span>()\n\n<span class="cm"># Contains (returns boolean mask)</span>\nnlp_rows = df[df[<span class="str">"text"</span>].str.<span class="fn">contains</span>(<span class="str">"NLP"</span>, case=<span class="kw">False</span>)]\n<span class="fn">print</span>(nlp_rows[<span class="str">"text"</span>].tolist())\n<span class="cm"># [\'Natural Language Processing is fun!\',</span>\n<span class="cm">#  \'transformers for NLP tasks\']</span>\n\n<span class="cm"># Regex in contains</span>\ndf[df[<span class="str">"text"</span>].str.<span class="fn">contains</span>(<span class="str">r"\\bN[A-Z]{2}\\b"</span>, regex=<span class="kw">True</span>)]  <span class="cm"># NLP, NER</span>\n\n<span class="cm"># startswith / endswith</span>\ndf[df[<span class="str">"text"</span>].str.<span class="fn">startswith</span>(<span class="str">"Deep"</span>)]\ndf[df[<span class="str">"text"</span>].str.<span class="fn">endswith</span>(<span class="str">"!"</span>)]\n\n<span class="cm"># strip whitespace (critical for real-world data!)</span>\ndf[<span class="str">"clean"</span>] = df[<span class="str">"text"</span>].str.<span class="fn">strip</span>()\n\n<span class="cm"># Split and expand</span>\ndf[<span class="str">"words"</span>] = df[<span class="str">"text"</span>].str.<span class="fn">split</span>()           <span class="cm"># list of words</span>\ndf[<span class="str">"word_count"</span>] = df[<span class="str">"text"</span>].str.<span class="fn">split</span>().str.<span class="fn">len</span>()  <span class="cm"># count words</span>\n\n<span class="cm"># Replace with regex</span>\ndf[<span class="str">"no_punct"</span>] = df[<span class="str">"text"</span>].str.<span class="fn">replace</span>(<span class="str">r"[^\\w\\s]"</span>, <span class="str">""</span>, regex=<span class="kw">True</span>)\n\n<span class="cm"># String length</span>\ndf[<span class="str">"char_len"</span>] = df[<span class="str">"text"</span>].str.<span class="fn">len</span>()</code></pre></div>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="cm"># .str.extract() \u2014 regex groups for structured extraction</span>\n\nemails = pd.<span class="fn">Series</span>([<span class="str">"alice@mit.edu"</span>, <span class="str">"bob@google.com"</span>, <span class="str">"carol@nyu.edu"</span>])\n\n<span class="cm"># Extract username and domain</span>\nextracted = emails.str.<span class="fn">extract</span>(<span class="str">r"(\\w+)@(\\w+)\\.(\\w+)"</span>)\nextracted.columns = [<span class="str">"user"</span>, <span class="str">"org"</span>, <span class="str">"tld"</span>]\n<span class="fn">print</span>(extracted)\n<span class="cm">#     user     org  tld</span>\n<span class="cm"># 0  alice     mit  edu</span>\n<span class="cm"># 1    bob  google  com</span>\n<span class="cm"># 2  carol     nyu  edu</span>\n\n<span class="cm"># NLP Preprocessing Pipeline with .str</span>\ntexts = pd.<span class="fn">Series</span>([<span class="str">"  Hello WORLD!  "</span>, <span class="str">"NLP is great."</span>, <span class="str">"Deep-Learning 101"</span>])\nclean = (texts\n    .str.<span class="fn">strip</span>()                              <span class="cm"># remove whitespace</span>\n    .str.<span class="fn">lower</span>()                              <span class="cm"># lowercase</span>\n    .str.<span class="fn">replace</span>(<span class="str">r"[^a-z\\s]"</span>, <span class="str">""</span>, regex=<span class="kw">True</span>)  <span class="cm"># remove non-alpha</span>\n    .str.<span class="fn">replace</span>(<span class="str">r"\\s+"</span>, <span class="str">" "</span>, regex=<span class="kw">True</span>)      <span class="cm"># normalize spaces</span>\n)\n<span class="fn">print</span>(clean.tolist())\n<span class="cm"># [\'hello world\', \'nlp is great\', \'deeplearning \']</span></code></pre></div>'

+ '<div class="calc-highlight"><strong>NLP tip:</strong> The <code>.str</code> accessor is your best friend for text preprocessing at scale. A pipeline of <code>.str.lower()</code> \u2192 <code>.str.replace()</code> \u2192 <code>.str.split()</code> can clean millions of text samples in seconds, much faster than applying Python functions row-by-row with <code>.apply()</code>.</div>'

