/* ============================================================
   SECTION 5: Sorting & Ranking
   ============================================================ */
+ '<h2 class="l-title">5. Sorting &amp; Ranking</h2>'

+ '<p class="l-text">Sorting lets you reorder rows by one or more columns. <code>sort_values()</code> sorts by column values, <code>sort_index()</code> sorts by the index. <code>rank()</code> assigns ordinal or statistical ranks to values.</p>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">import</span> pandas <span class="kw">as</span> pd\n\ndf = pd.<span class="fn">DataFrame</span>({\n    <span class="str">"name"</span>: [<span class="str">"Alice"</span>, <span class="str">"Bob"</span>, <span class="str">"Carol"</span>, <span class="str">"Dave"</span>, <span class="str">"Eve"</span>, <span class="str">"Frank"</span>],\n    <span class="str">"age"</span>: [<span class="num">25</span>, <span class="num">30</span>, <span class="num">28</span>, <span class="num">35</span>, <span class="num">22</span>, <span class="num">40</span>],\n    <span class="str">"score"</span>: [<span class="num">88</span>, <span class="num">72</span>, <span class="num">95</span>, <span class="num">60</span>, <span class="num">91</span>, <span class="num">85</span>],\n    <span class="str">"field"</span>: [<span class="str">"NLP"</span>, <span class="str">"CV"</span>, <span class="str">"RL"</span>, <span class="str">"NLP"</span>, <span class="str">"CV"</span>, <span class="str">"NLP"</span>]\n})\n\n<span class="cm"># Sort by single column</span>\ndf.<span class="fn">sort_values</span>(<span class="str">"score"</span>, ascending=<span class="kw">False</span>)\n<span class="cm">#     name  age  score field</span>\n<span class="cm"># 2  Carol   28     95    RL</span>\n<span class="cm"># 4    Eve   22     91    CV</span>\n<span class="cm"># 0  Alice   25     88   NLP</span>\n<span class="cm"># 5  Frank   40     85   NLP</span>\n<span class="cm"># 1    Bob   30     72    CV</span>\n<span class="cm"># 3   Dave   35     60   NLP</span>\n\n<span class="cm"># Multi-column sort: first by field, then by score descending</span>\ndf.<span class="fn">sort_values</span>([<span class="str">"field"</span>, <span class="str">"score"</span>], ascending=[<span class="kw">True</span>, <span class="kw">False</span>])\n\n<span class="cm"># Sort by index</span>\ndf.<span class="fn">sort_index</span>(ascending=<span class="kw">False</span>)\n\n<span class="cm"># nlargest / nsmallest \u2014 faster than sort + head</span>\ntop3 = df.<span class="fn">nlargest</span>(<span class="num">3</span>, <span class="str">"score"</span>)\n<span class="fn">print</span>(top3[<span class="str">"name"</span>].tolist())  <span class="cm"># [\'Carol\', \'Eve\', \'Alice\']</span>\n\nbottom2 = df.<span class="fn">nsmallest</span>(<span class="num">2</span>, <span class="str">"age"</span>)\n<span class="fn">print</span>(bottom2[<span class="str">"name"</span>].tolist())  <span class="cm"># [\'Eve\', \'Alice\']</span></code></pre></div>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="cm"># Ranking methods</span>\ndf[<span class="str">"rank_default"</span>] = df[<span class="str">"score"</span>].<span class="fn">rank</span>(ascending=<span class="kw">False</span>)  <span class="cm"># average ties</span>\ndf[<span class="str">"rank_min"</span>]     = df[<span class="str">"score"</span>].<span class="fn">rank</span>(method=<span class="str">"min"</span>, ascending=<span class="kw">False</span>)\ndf[<span class="str">"rank_dense"</span>]   = df[<span class="str">"score"</span>].<span class="fn">rank</span>(method=<span class="str">"dense"</span>, ascending=<span class="kw">False</span>)\n\n<span class="cm"># Rank methods:</span>\n<span class="cm">#   \'average\' \u2014 tied values get mean rank (default)</span>\n<span class="cm">#   \'min\'     \u2014 tied values get lowest rank (1224 style)</span>\n<span class="cm">#   \'max\'     \u2014 tied values get highest rank</span>\n<span class="cm">#   \'first\'   \u2014 tied values ranked by position in data</span>\n<span class="cm">#   \'dense\'   \u2014 like min, but no gaps (1223 style)</span>\n\n<span class="cm"># Percentile rank</span>\ndf[<span class="str">"percentile"</span>] = df[<span class="str">"score"</span>].<span class="fn">rank</span>(pct=<span class="kw">True</span>)\n<span class="fn">print</span>(df[[<span class="str">"name"</span>,<span class="str">"score"</span>,<span class="str">"percentile"</span>]])\n<span class="cm">#     name  score  percentile</span>\n<span class="cm"># 0  Alice     88    0.666667</span>\n<span class="cm"># 1    Bob     72    0.333333</span>\n<span class="cm"># 2  Carol     95    1.000000</span>\n<span class="cm"># 3   Dave     60    0.166667</span>\n<span class="cm"># 4    Eve     91    0.833333</span>\n<span class="cm"># 5  Frank     85    0.500000</span></code></pre></div>'

