+ 'var t2={x:pass_idx.map(function(i){return ages[i]}),y:pass_idx.map(function(i){return scores[i]}),text:pass_idx.map(function(i){return names[i]}),mode:"markers+text",textposition:"top center",name:"puan > 80 & yas < 35",marker:{color:"#4de87a",size:14,line:{color:"#4de87a",width:2}},textfont:{color:"#4de87a",size:11}};'
